create function orulo_audit.batch_has_image(p jsonb) returns boolean language sql immutable set search_path='' as $$
 select coalesce(exists(select 1 from unnest(array['image_url','url','2280x1800','1024x1024','520x280']) k where jsonb_typeof(p->k)='string' and length(p->>k)>0)
 or (jsonb_typeof(p->'images')='array' and p->'images'<>'[]'::jsonb),false);
$$;
create function orulo_audit.batch_missing_ids(raw jsonb) returns jsonb language sql immutable set search_path='' as $$
 select coalesce(jsonb_agg(p->>'id' order by p->>'id'),'[]'::jsonb)
 from jsonb_array_elements(case when jsonb_typeof(raw->'building'->'floor_plans')='array' then raw->'building'->'floor_plans' else '[]'::jsonb end)p where not orulo_audit.batch_has_image(p);
$$;
create function orulo_audit.batch_merge(raw jsonb,patches jsonb) returns jsonb language plpgsql immutable set search_path='' as $$
declare x jsonb; k text; v jsonb; pattern constant text:='^https://static[.]orulo[.]com[.]br/images/properties/[A-Za-z0-9_-]+/[A-Za-z0-9_-]+[.](jpg|jpeg|png|webp)$';
begin
 if jsonb_typeof(patches) is distinct from 'array' or jsonb_array_length(patches)>1000 or jsonb_typeof(raw->'building'->'floor_plans') is distinct from 'array' then raise exception 'BATCH_PATCH_INVALID'; end if;
 if (select count(*)<>count(distinct p->>'id') from jsonb_array_elements(patches)p) then raise exception 'BATCH_DUPLICATE_PLAN_ID'; end if;
 if (select count(*)<>count(distinct p->>'id') from jsonb_array_elements(raw->'building'->'floor_plans')p) then raise exception 'BATCH_EXISTING_PLAN_IDS_INVALID'; end if;
 for x in select * from jsonb_array_elements(patches) loop
  if x->>'id' is null or x->>'image_url' is null or not(x->>'image_url'~pattern) or not exists(select 1 from jsonb_array_elements(raw->'building'->'floor_plans')p where p->>'id'=x->>'id') then raise exception 'BATCH_PATCH_PLAN_MISMATCH'; end if;
  for k,v in select * from jsonb_each(x) loop
   if k='id' then continue; end if;
   if k='images' then
    if jsonb_typeof(v) is distinct from 'array' or exists(select 1 from jsonb_array_elements(v)u where jsonb_typeof(u)<>'string' or not(u#>>'{}'~pattern)) then raise exception 'BATCH_IMAGE_URL_INVALID'; end if;
   elsif k not in ('image_url','url','2280x1800','1024x1024','520x280') or jsonb_typeof(v)<>'string' or not(v#>>'{}'~pattern) then raise exception 'BATCH_IMAGE_FIELDS_ONLY'; end if;
  end loop;
 end loop;
 return (select coalesce(jsonb_agg(case when orulo_audit.batch_has_image(p) then p else p||coalesce((select z-'id' from jsonb_array_elements(patches)z where z->>'id'=p->>'id'),'{}'::jsonb) end order by n),'[]'::jsonb) from jsonb_array_elements(raw->'building'->'floor_plans') with ordinality a(p,n));
end$$;
create function orulo_audit.batch_inventory(batch_id text) returns jsonb language plpgsql set search_path='' as $$
declare c jsonb; bids text[]; live jsonb; x jsonb;
begin
 c:=orulo_audit.batch_catalog()->'batches'->batch_id;if c is null then raise exception 'BATCH_UNKNOWN'; end if;
 select array_agg(v) into bids from jsonb_array_elements_text(c->'buildingIds')v;
 with matched as materialized(
  select id,raw_data->>'building_id' bid,raw_data raw from public.properties where source='novos' and state='SP' and active is true and raw_data->>'building_id'=any(bids)
  union all select id,raw_data->'building'->>'id',raw_data from public.properties where source='novos' and state='SP' and active is true and raw_data->>'building_id' is null and raw_data->'building'->>'id'=any(bids))
 select coalesce(jsonb_agg(jsonb_build_object('id',id,'buildingId',bid,'missingPlanIds',orulo_audit.batch_missing_ids(raw)) order by id) filter(where orulo_audit.batch_missing_ids(raw)<>'[]'::jsonb),'[]'::jsonb) into live from matched;
 for x in select * from jsonb_array_elements(live) loop
  if not exists(select 1 from jsonb_array_elements(c->'targets')a where a->>'id'=x->>'id' and a->>'buildingId'=x->>'buildingId' and (a->'missingPlanIds') @> (x->'missingPlanIds')) then raise exception 'BATCH_MANIFEST_DRIFT'; end if;
 end loop;
 return jsonb_build_object('batchId',batch_id,'masterHash',orulo_audit.batch_catalog()->>'masterHash','batchManifestHash',c->>'hash','targets',live);
end$$;
create function orulo_audit.batch_auth(r uuid) returns jsonb language plpgsql set search_path='' as $$
declare a jsonb; c jsonb;
begin
 if (select count(*) from orulo_audit.entries where run_uuid=r and kind='WRITE_AUTHORIZED')<>1 then raise exception 'BATCH_EXPLICIT_AUTHORIZATION_REQUIRED'; end if;
 select event into a from orulo_audit.entries where run_uuid=r and kind='WRITE_AUTHORIZED';c:=orulo_audit.batch_catalog()->'batches'->(a->>'batchId');
 if a->>'mode' is distinct from 'BATCH_IMAGES' or c is null or c->>'released' is distinct from 'true' or a->>'masterHash' is distinct from orulo_audit.batch_catalog()->>'masterHash' or a->>'batchManifestHash' is distinct from c->>'hash' or a->>'expiresAt' is null or (a->>'expiresAt')::timestamptz<clock_timestamp() then raise exception 'BATCH_AUTHORIZATION_INVALID_OR_EXPIRED'; end if;
 return a;
end$$;
alter function orulo_audit.authorize_pilot(uuid,text,text,text,text) rename to authorize_single_pilot;
create function orulo_audit.authorize_pilot(p_run uuid,p_expected_head text,p_github_run_id text,p_control_sha text,p_reason text) returns jsonb
 language plpgsql security definer set search_path='' set timezone='UTC' set synchronous_commit='on' as $$
declare e orulo_audit.entries%rowtype;r orulo_audit.runs%rowtype;c jsonb;inventory jsonb;x jsonb;expected jsonb;ids jsonb;patch_ids jsonb;
begin
 if current_setting('role',true)='service_role' or session_user not in ('postgres','supabase_admin') then raise insufficient_privilege; end if;
 perform orulo_audit.lock_run(p_run);select * into e from orulo_audit.entries where run_uuid=p_run order by sequence desc limit 1;
 if e.event->>'stage' is distinct from 'BATCH_PLAN' then return orulo_audit.authorize_single_pilot(p_run,p_expected_head,p_github_run_id,p_control_sha,p_reason); end if;
 select * into r from orulo_audit.runs where run_uuid=p_run;c:=orulo_audit.batch_catalog()->'batches'->(e.event->>'batchId');
 if c is null or c->>'released' is distinct from 'true' then raise exception 'BATCH_PHASE_NOT_RELEASED'; end if;
 if c->>'prerequisite' is not null and not exists(select 1 from orulo_audit.entries where kind='FINISHED' and event->>'batchId'=c->>'prerequisite' and event->>'masterHash'=orulo_audit.batch_catalog()->>'masterHash') then raise exception 'BATCH_PREVIOUS_RESULT_REQUIRED'; end if;
 if r.github_run_id is distinct from p_github_run_id or r.metadata->>'workflowSha' is distinct from p_control_sha or coalesce(p_control_sha,'')!~'^[a-f0-9]{40}$' or e.hash is distinct from p_expected_head or e.kind<>'CLIENT_READBACK' or e.created_at<clock_timestamp()-interval '10 minutes' or length(trim(p_reason))<10 or p_reason is null or exists(select 1 from orulo_audit.entries where run_uuid=p_run and kind in ('WRITE_AUTHORIZED','BASELINE_V2','ABORTED','FINISHED')) then raise exception 'BATCH_PLAN_OR_HEAD_INVALID'; end if;
 inventory:=orulo_audit.batch_inventory(e.event->>'batchId');
 if e.event->>'masterHash' is distinct from inventory->>'masterHash' or e.event->>'batchManifestHash' is distinct from inventory->>'batchManifestHash' or jsonb_array_length(inventory->'targets')=0 or jsonb_array_length(inventory->'targets')>500 then raise exception 'BATCH_TARGETS_INVALID'; end if;
 select jsonb_agg(z->>'id' order by z->>'id') into ids from jsonb_array_elements(inventory->'targets')z;
 if ids is distinct from e.event->'targetIds' or jsonb_array_length(e.event->'targets')<>jsonb_array_length(ids) then raise exception 'BATCH_TARGETS_CHANGED'; end if;
 if jsonb_typeof(e.event->'targets') is distinct from 'array' or (select count(*)<>count(distinct t->>'id') from jsonb_array_elements(e.event->'targets')t) then raise exception 'BATCH_DUPLICATE_TARGET'; end if;
 for x in select * from jsonb_array_elements(e.event->'targets') loop
  select v into expected from jsonb_array_elements(inventory->'targets')v where v->>'id'=x->>'id' and v->>'buildingId'=x->>'buildingId';
  select jsonb_agg(p->>'id' order by p->>'id') into patch_ids from jsonb_array_elements(x->'patches')p;
  if expected is null or patch_ids is distinct from expected->'missingPlanIds' then raise exception 'BATCH_PLAN_COVERAGE_INVALID'; end if;
  perform orulo_audit.batch_merge(raw_data,x->'patches') from public.properties where id=(x->>'id')::uuid;
 end loop;
 return orulo_audit.append(p_run,e.sequence+1,e.hash,jsonb_build_object('type','WRITE_AUTHORIZED','eventUuid',gen_random_uuid(),'mode','BATCH_IMAGES',
  'batchId',e.event->>'batchId','masterHash',inventory->>'masterHash','batchManifestHash',inventory->>'batchManifestHash','targetIds',ids,'planSequence',e.sequence,'planHash',e.hash,'controlSha',p_control_sha,'expiresAt',clock_timestamp()+interval '30 minutes','reason',p_reason));
end$$;
alter function public.orulo_audited_cas(uuid,uuid) set schema orulo_audit;
alter function orulo_audit.orulo_audited_cas(uuid,uuid) rename to pilot_cas_guard;
create function public.orulo_audited_cas(p_run uuid,p_operation uuid) returns jsonb language plpgsql security definer set search_path='' set timezone='UTC' set synchronous_commit='on' set lock_timeout='5s' as $$
declare a jsonb;i orulo_audit.entries%rowtype;b orulo_audit.entries%rowtype;plan jsonb;target jsonb;expected public.properties%rowtype;j jsonb;
begin
 perform orulo_audit.require_service();perform orulo_audit.lock_run(p_run);
 if not exists(select 1 from orulo_audit.entries where run_uuid=p_run and kind='WRITE_AUTHORIZED' and event->>'mode'='BATCH_IMAGES') then return orulo_audit.pilot_cas_guard(p_run,p_operation); end if;
 a:=orulo_audit.batch_auth(p_run);select * into i from orulo_audit.entries where run_uuid=p_run and kind='INTENT' and operation_uuid=p_operation;
 if not found then raise exception 'AUDIT_DURABLE_INTENT_REQUIRED'; end if;
 select event into plan from orulo_audit.entries where run_uuid=p_run and sequence=(a->>'planSequence')::bigint and hash=a->>'planHash';
 select x into target from jsonb_array_elements(plan->'targets')x where x->>'id'=i.event->>'id';
 if target is null or not(a->'targetIds' ? (i.event->>'id')) or coalesce(i.event->'expected'->'raw_data'->>'building_id',i.event->'expected'->'raw_data'->'building'->>'id') is distinct from target->>'buildingId' then raise exception 'BATCH_ROW_SCOPE_DENIED'; end if;
 if exists(select 1 from orulo_audit.entries where run_uuid=p_run and kind='CAS_RESULT' and event->>'id'=i.event->>'id') then raise exception 'BATCH_ROW_ALREADY_ATTEMPTED'; end if;
 select * into b from orulo_audit.entries where run_uuid=p_run and kind='BASELINE_V2';
 if not found or b.created_at<clock_timestamp()-interval '5 minutes' or b.event->'snapshot'->>'membershipStable' is distinct from 'true' or (b.event->'snapshot'->>'beginSequence')::bigint <= (select sequence from orulo_audit.entries where run_uuid=p_run and kind='WRITE_AUTHORIZED') or b.event->'snapshot'->'columns' is distinct from orulo_audit.columns_v2() then raise exception 'BATCH_FRESH_BASELINE_REQUIRED'; end if;
 select * into expected from jsonb_populate_record(null::public.properties,i.event->'expected');
 j:=to_jsonb(expected)||jsonb_build_object('created_at',expected.created_at at time zone 'UTC','updated_at',expected.updated_at at time zone 'UTC');
 if not exists(select 1 from orulo_audit.snapshot_records where run_uuid=p_run and kind='BASELINE_V2' and id=expected.id and record->>2=target->>'buildingId' and record->>4=md5(j::text)) then raise exception 'BATCH_EXPECTED_DIFFERS_FROM_BASELINE'; end if;
 if i.event->'desiredPlans' is distinct from orulo_audit.batch_merge(expected.raw_data,target->'patches') then raise exception 'BATCH_PATCH_DIFFERS_FROM_AUTHORIZED_PLAN'; end if;
 return orulo_audit.audited_cas_core(p_run,p_operation);
end$$;
alter function public.orulo_audit_control(text,uuid,bigint,text,jsonb) set schema orulo_audit;
alter function orulo_audit.orulo_audit_control(text,uuid,bigint,text,jsonb) rename to control_pilot;
create function public.orulo_audit_control(p_action text,p_run uuid default null,p_sequence bigint default null,p_previous_hash text default null,p_event jsonb default '{}'::jsonb) returns jsonb
 language plpgsql security definer set search_path='' set timezone='UTC' set synchronous_commit='on' set lock_timeout='5s' as $$
declare a jsonb;e orulo_audit.entries%rowtype;p public.properties%rowtype;j jsonb;c jsonb;bad bigint;written bigint;comparison jsonb;
begin
 perform orulo_audit.require_service();
 if p_action='health' then return orulo_audit.control_pilot('health')||jsonb_build_object('batchProtocol',1,'batchMasterHash',orulo_audit.batch_catalog()->>'masterHash'); end if;
 if p_action='batch_inventory' then return orulo_audit.batch_inventory(p_event->>'batchId'); end if;
 if p_action='batch_row' then
  c:=orulo_audit.batch_catalog()->'batches'->(p_event->>'batchId');select * into p from public.properties where id=(p_event->>'id')::uuid;
  if not found or not orulo_audit.scope_ok(to_jsonb(p)) or not exists(select 1 from jsonb_array_elements(c->'targets')x where x->>'id'=p.id::text and x->>'buildingId'=coalesce(p.raw_data->>'building_id',p.raw_data->'building'->>'id')) then raise exception 'BATCH_ROW_SCOPE_DENIED'; end if;
  j:=to_jsonb(p)||jsonb_build_object('created_at',p.created_at at time zone 'UTC','updated_at',p.updated_at at time zone 'UTC');return jsonb_build_object('row',to_jsonb(p),'fullHash',md5(j::text),'contentHash',md5((j-'updated_at')::text));
 end if;
 if p_action='batch_status' then
  select * into e from orulo_audit.entries where run_uuid=p_run and kind='WRITE_AUTHORIZED';if not found then return 'null'::jsonb; end if;perform orulo_audit.batch_auth(p_run);
  return jsonb_build_object('runUuid',p_run,'sequence',e.sequence,'hash',e.hash,'eventUuid',e.event_uuid);
 end if;
 if p_action='append' and p_event->>'type'='INTENT' and exists(select 1 from orulo_audit.entries where run_uuid=p_run and kind='WRITE_AUTHORIZED' and event->>'mode'='BATCH_IMAGES') then
  perform orulo_audit.lock_run(p_run);a:=orulo_audit.batch_auth(p_run);
  if not(a->'targetIds' ? (p_event->>'id')) then raise exception 'BATCH_ROW_SCOPE_DENIED'; end if;
  return orulo_audit.control_paged(p_action,p_run,p_sequence,p_previous_hash,p_event);
 end if;
 if p_action<>'batch_finish' then return orulo_audit.control_pilot(p_action,p_run,p_sequence,p_previous_hash,p_event); end if;
 perform orulo_audit.lock_run(p_run);a:=orulo_audit.batch_auth(p_run);
 if exists(select 1 from orulo_audit.entries i where i.run_uuid=p_run and i.kind='INTENT' and not exists(select 1 from orulo_audit.entries x where x.run_uuid=p_run and x.kind='CAS_RESULT' and x.operation_uuid=i.operation_uuid)) then raise exception 'AUDIT_PENDING_INTENT'; end if;
 if (select count(*) from orulo_audit.entries where run_uuid=p_run and kind in ('BASELINE_V2','READBACK_V2'))<>2 then raise exception 'AUDIT_TWO_SNAPSHOTS_REQUIRED'; end if;
 comparison:=orulo_audit.compare_v2(p_run);
 if comparison->>'schemaMatch' is distinct from 'true' or comparison->>'captureStable' is distinct from 'true' then raise exception 'BATCH_SNAPSHOT_INTEGRITY_FAILED'; end if;
 with b as(select id,record from orulo_audit.snapshot_records where run_uuid=p_run and kind='BASELINE_V2' and record->>4 is not null),
 d as(select id,record from orulo_audit.snapshot_records where run_uuid=p_run and kind='READBACK_V2' and record->>4 is not null),
 x as(select coalesce(b.id,d.id) id,b.record before,d.record after from b full join d using(id)),
 checked as(select x.*,c.event->'result' result from x left join orulo_audit.entries c on c.run_uuid=p_run and c.kind='CAS_RESULT' and c.event->>'id'=x.id::text)
 select count(*) filter(where not coalesce(case when result is not null then result->>'status'='UPDATED' and result->'receipt'->>'verified'='true'
  and before->>4=result->'receipt'->>'beforeFullHash' and after->>4=result->'receipt'->>'afterFullHash' and before->>5=result->'receipt'->>'expectedBeforeContentHash' and after->>5=result->'receipt'->>'expectedAfterContentHash'
 else before->>4=after->>4 and before->>5=after->>5 end,false)),count(*) filter(where result->>'status'='UPDATED') into bad,written from checked;
 if bad<>0 then raise exception 'BATCH_UNATTRIBUTED_GLOBAL_CHANGE'; end if;
 return orulo_audit.append(p_run,p_sequence,p_previous_hash,jsonb_build_object('type','FINISHED','eventUuid',p_event->>'eventUuid','mode','BATCH_IMAGES','batchId',a->>'batchId','masterHash',a->>'masterHash','batchManifestHash',a->>'batchManifestHash','rowsWritten',written,'comparison',comparison,'writeEnabled',false,'nextBatchAuthorized',false));
end$$;
alter function orulo_audit.batch_catalog() owner to orulo_audit_owner;
alter function orulo_audit.batch_has_image(jsonb) owner to orulo_audit_owner;
alter function orulo_audit.batch_missing_ids(jsonb) owner to orulo_audit_owner;
alter function orulo_audit.batch_merge(jsonb,jsonb) owner to orulo_audit_owner;
alter function orulo_audit.batch_inventory(text) owner to orulo_audit_owner;
alter function orulo_audit.batch_auth(uuid) owner to orulo_audit_owner;
alter function orulo_audit.authorize_pilot(uuid,text,text,text,text) owner to orulo_audit_owner;
alter function public.orulo_audit_control(text,uuid,bigint,text,jsonb) owner to orulo_audit_owner;
alter function public.orulo_audited_cas(uuid,uuid) owner to orulo_audit_owner;
revoke all on all functions in schema orulo_audit from public,anon,authenticated,service_role;
revoke all on function public.orulo_audit_control(text,uuid,bigint,text,jsonb),public.orulo_audited_cas(uuid,uuid) from public,anon,authenticated;
grant execute on function public.orulo_audit_control(text,uuid,bigint,text,jsonb),public.orulo_audited_cas(uuid,uuid) to service_role;
revoke create on schema public from orulo_audit_owner;
notify pgrst,'reload schema';
commit;
